export const POWERWORLD_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/powerworld-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getPowerWorldStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(POWERWORLD_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
